    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;             // 限时 n 分钟，前四圈分别跑了 a b c d 分钟

    // 五圈必须全部跑完，前四圈花掉的时间一秒也省不掉，
