#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;                                  // n 个学习小组，共 2n 名学生
    vector<int> firstPos(n + 1, 0);            // firstPos[g]：第 g 组到目前为止见到的第一个学生编号
    vector<int> ans(2 * n + 1, 0);             // ans[i]：第 i 名学生的队友

    for (int i = 1; i <= 2 * n; i++) {
        int g;
        cin >> g;
        if (firstPos[g] == 0) {
            firstPos[g] = i;                   // 组里第一个出现的学生，先记下位置
        } else {
            // 组里第二个出现的学生：两人互为答案，一次填好两边。
            ans[i] = firstPos[g];
            ans[firstPos[g]] = i;
        }
    }

    for (int i = 1; i <= 2 * n; i++) {
        if (i > 1) cout << " ";
        cout << ans[i];
    }
    cout << "\n";
    return 0;
}
```

### 易错点

一次配对要填写双方答案，输出的是学生编号。

